import json,numpy as np
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'revision_20261009';M=R/'manuscript'
def read(p):return json.loads((R/p).read_text(encoding='utf-8'))
def fmt(x,d=3):return 'Undefined' if x is None or not np.isfinite(x) else f'{x:.{d}f}'
bs=[{'type':'title','text':'Supplementary methods and results'}, {'type':'paragraph','text':'Companion to: When does decision-focused learning add value to residential battery control? Private costs and AC feeder consequences.'}]
def h(text):bs.append({'type':'heading','text':text})
def p(text):bs.append({'type':'paragraph','text':text})
def tab(caption,headers,rows,note):bs.append({'type':'table','caption':caption,'headers':headers,'rows':rows,'note':note})
j=read('network_revision_summary.json');ctl=read('results/control_transfer_summary.json')
h('S1. Source chronology, coverage and sample formation')
p('The source-clock half-hours and data-quality indicators are retained. Nominal PV capacity is taken from information available before each target day, not estimated by outcome maximization. Known-household training has 132,200 days and validation 44,373; test evaluation has 88,609 known and 20,032 held-out GC/PV-valid days. The CL-valid absolute-cost sample is 107,713 days. Estimated measurements and required-channel gaps are excluded, and no missing meter record is synthesized. Feeder complete dates must satisfy every assigned household’s required channels. The expanded private comparison and joint feeder comparison thus answer different estimands.')
cov=j['calendar_coverage'];months=list(cov[0]['months']);rows=[]
