rows.append(['Total','365']+[str(x['clean_days']) for x in cov])
tab('Table S1a. Jointly clean dates by calendar month.',['Month','Calendar','Panel 1','Panel 2','Panel 3','Held-out'],rows,'Counts are actual evaluated dates, not bootstrap replicates. Panel 2 coverage is 35.3% of the calendar. Zero months remain in the calendar-axis resampling array.')
raw=np.load(ROOT/'datasets/ausgrid_source_clock_panel.npz');dates=raw['date'].astype(str);dh={d:i for i,d in enumerate(dates)};hh={int(h):i for i,h in enumerate(raw['household_id'])};records=read('network_diagnostics/scenarios.json')['records'];rows=[]
for pi in range(4):
 q=next(x for x in records if x['metadata']['objective']=='msecont' and x['metadata']['seed']==11 and x['metadata']['panel']==pi and x['metadata']['battery_count']==55 and x['metadata']['tariff_mix']=='all_tou' and x['metadata']['comparison_group'] in (None,'original_physical') and x['metadata']['parameters']['network']=='eulv' and x['metadata']['parameters']['source_pu']==1.05 and x['metadata']['parameters'].get('mapping_seed') is None and x['metadata']['parameters'].get('power_factor',.95)==.95 and x['metadata']['parameters'].get('impedance_scale',1.0)==1.0 and x['metadata']['parameters'].get('export_limit_kw') is None)
 z=np.load(R/'network_diagnostics'/(q['scenario_id']+'.npz'));hs=[hh[int(x)] for x in z['household_id']];ds=[dh[x] for x in z['date'].astype(str)];v=raw['power_kw'][hs][:,ds];clean=z['clean_day'];valid=raw['valid_feeder_day'][hs][:,ds]
 gross=(v[...,0]+v[...,1]).sum(axis=2)*.5;pv=v[...,2].sum(axis=2)*.5
 rows.append([str(pi+1) if pi<3 else 'Held-out',str(int(clean.sum())),fmt(gross[:,clean].mean(),2),fmt(pv[:,clean].mean(),2),str(int(valid.sum())),fmt(gross[valid].mean(),2),fmt(pv[valid].mean(),2)])
tab('Table S1b. Load and PV on retained feeder dates versus individually valid dates.',['Panel','Joint dates','Joint demand (kWh/day)','Joint PV (kWh/day)','Individual days','Individual demand','Individual PV'],rows,'Both descriptions use observed gross GC+CL and PV. Individually valid days need not support all-site AC replay and are not a missing-data correction. Main private GC/PV comparisons additionally allow CL cancellation.')
h('S2. Learning and baseline specifications')
p('The 774-input PV network uses 128/64 ReLU hidden units and 48 softplus outputs. Supervised configuration selection precedes three-seed initialization. DFL and continued MSE share 4,096 training pairs, 1,024 validation pairs, batch 32, four epochs, AdamW weight decay 10⁻⁴, gradient clipping at norm 1, and learning-rate candidates 10⁻⁴ and 3×10⁻⁵. Initial checkpoints are eligible; downstream validation cost chooses each arm’s checkpoint. All initialization, sampling and selection records are retained, including unsuccessful settings. Night restriction fixes 00:00–04:00 and 21:00–24:00 to zero. Its initial introduction followed an Ausgrid test diagnostic and is not represented as preregistration.')
p('Three-offset and twelve-offset calibration use bounds 0.25×tanh(parameter) in capacity-normalized units, three epochs of Adam at 0.03 and training batch 32. Calibration uses 2,048 known training and 2,048 validation examples. Validation chooses shrinkage in {0,0.25,0.5,0.75,1}. The seasonal variant crosses three fixed daytime windows with DJF/MAM/JJA/SON. Direct net-load prediction uses signed linear outputs, the same inputs, and full training/validation splits; two prespecified AdamW configurations are selected by validation MSE with at most 30 epochs and patience six. Six four-hour windows by four seasons give 24 cost-calibration parameters. An explicit support-matched nighttime projection and the unrestricted signed diagnostic are retained separately where available; revision chronology is disclosed in the main Methods.')
p('The stronger demand network has 256/128 hidden units and softplus outputs. Validation chooses the mixture of the original HGB and this network among weights 0,0.25,0.5,0.75,1; it selects 0.5. A previous-day profile is the persistence comparator. Residual scenarios use the original frozen forecast backbone and 20 joint load/PV daily residual paths from 147 clean validation dates. A deterministic donor policy supplies household-held-out residuals. Shared battery actions apply in every scenario; no oracle recourse, network coordination or test residual fitting is introduced.')
rows=[]
for t in ('tou','flat'):
 e=read(f'results/expanded_comparison_{t}_support_matched_baselines.json');c=e['cohorts']['all299'];ref=e['reference']
 signed=read(f'results/expanded_comparison_{t}_all_baselines.json')['cohorts']['all299']
 entries=[(name,v,c) for name,v in c['absolute'].items()]+[(name,v,signed) for name,v in signed['absolute'].items() if name.startswith(('net_mse_'+t,'net_calibrated24_'+t))]
 for name,v,cohort in entries:
  z=np.load(R/'dispatch'/(name+'.npz'));mask=z['clean_day'];tp=float(z['energy_throughput_kwh'][mask].mean());q=cohort['paired'].get(name+'__minus__'+ref)
  rows.append([t,name.split('_'+t)[0],fmt(v['mean_full_operating_cost'],5),fmt(v['mean_retail_only'],5),fmt(tp),fmt(100*q['micro_mean_difference']) if q else '0', 'Reference' if q is None else f"{fmt(q['micro_calendar_block95'][0]*100)} to {fmt(q['micro_calendar_block95'][1]*100)}"])
tab('Table S2. Complete all-household baseline comparison.',['Tariff','Method','Full cost','Retail','Throughput','Paired Δ (cents)','95% interval'],rows,'Cost and retail: AUD/day, same 107,713 CL-valid days; listed throughput is independently reaggregated on that same mask. Paired Δ uses 108,641 GC/PV days, identical CL charge cancels. Negative Δ favors the row method over continued MSE. Seed 11; unsuccessful candidates are retained.')
pm=read('results/revision_predictive_metrics.json')
p('Predictive metrics are diagnostic, not downstream selection criteria for task learning. The common and selected mixed demand validation RMSEs are 0.547316 and 0.542329 kW, respectively; the neural-only demand model has 0.5510 kW validation RMSE. On the 244 known households and 88,609 test household-days, the original unrestricted signed direct-net MSE has about 0.6253 kW test RMSE versus about 0.6184 kW for the separated MSE net input. These diagnostic values precede the support-matched revision and do not establish a stronger direct-net baseline or architecture necessity. Complete split and role metrics accompany the machine-readable reproduction records.')
h('S3. Resource conditions and numerical definitions')
p('Resource timings use 1,024 fixed validation pairs, 20 warmups and three serial method repeats, with one numerical thread per subprocess. Other revision calculations run concurrently. Windows CPU-clock granularity affects individual process-CPU measurements; both wall and CPU summaries are retained. Common original supervised fitting is excluded. Continued-MSE/DFL resource refits reproduce their original fitting protocol, while performance uses the original frozen models. All sample counts, validation procedures and memory scope are reported rather than treating different fitting procedures as equal-budget attribution tests.')
res=read('results/resource_comparison_tou.json');rows=[]
for k,v in res['rows'].items():rows.append([k,fmt(v['training_seconds_including_validation_selection'],2),fmt(v['mean_qp_ms']),fmt(v['p95_qp_ms']),fmt(v['mean_process_cpu_qp_ms']),fmt(v['inference_peak_rss_mb'],1),fmt(v.get('training_peak_rss_mb'),1)])
tab('Table S3. Full resource measurement.',['Method','Learn (s)','Mean wall (ms)','p95 wall (ms)','Mean CPU (ms)','Replay RSS (MB)','Learn RSS (MB)'],rows,'RSS includes interpreter, dependencies and loaded arrays. No memory claim for a hypothetical embedded deployment is inferred. SAA learning is residual extraction only.')
